PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?film ?filmLabel ?director ?directorLabel ?birthDate WHERE {
  {
    BIND(<http://dbpedia.org/resource/Arr%C3%AAte_ton_cin%C3%A9ma> AS ?film)
    BIND(dbr:Diane_Kurys AS ?director)
  } UNION {
    BIND(<http://dbpedia.org/resource/Agni_%282004_film%29> AS ?film)
    BIND(dbr:Swapan_Saha AS ?director)
